package org.sormus.downloads;
public final class TransferInboxTest {
 public static void main(String[] args){TransferInbox<Integer> q=new TransferInbox<>(2);if(!q.offer("a",1)||!q.offer("b",2)||q.offer("c",3)||q.offer("a",4))throw new Error("Admission bounds or duplicate guard failed.");if(q.poll()!=1||!q.offer("c",3)||q.poll()!=2||q.poll()!=3||q.poll()!=null||q.offer("a",4))throw new Error("FIFO or completed-batch deduplication failed.");if(!q.offer("d",4))throw new Error();q.clear();if(!q.isEmpty()||q.offer("d",4))throw new Error("Cancelled batches were redelivered.");for(String action:new String[]{"android.intent.action.SEND","android.intent.action.SEND_MULTIPLE","android.intent.action.VIEW"})if(!TransferInbox.external(action))throw new Error();if(TransferInbox.external("android.intent.action.MAIN")||TransferInbox.external(null))throw new Error("Launcher is not a received transfer.");System.out.println("Received transfer FIFO, capacity, duplicate/cancel guards and launcher separation passed.");}
}
